<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login();$rows=$pdo->query("SELECT b.*,u.full_name FROM bills b JOIN users u ON u.id=b.cashier_id ORDER BY b.id DESC")->fetchAll();?><!doctype html><html lang="sw"><head><meta charset="utf-8"><title>Bills Zote</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="container"><div class="text-center"><h2>RESTAURANT - BILLS REPORT</h2><p><?=date('Y-m-d H:i')?></p></div><table><tr><th>#</th><th>Bill</th><th>Mteja</th><th>Total</th><th>Status</th><th>Cashier</th><th>Tarehe</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['bill_no'])?></td><td><?=e($r['customer_name']?:'Walk-in')?></td><td><?=number_format($r['total'],2)?></td><td><?=e($r['status'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table><div class="actions no-print"><button onclick="window.print()">Print</button></div></div></body></html>
